function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 30) return 'grid needs 1 to 30 rows.';
  const cols = grid[0].length;
  if (cols < 1 || cols > 30) return 'grid needs 1 to 30 columns.';
  for (const row of grid) {
    if (row.length !== cols) return 'Every row must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Each cell is 0 or 1.';
  }
  return null;
}

