function minDays(grid) {
  // Try removing every set of 0, 1, 2, ... land cells and count islands with union-find.
  const rows = grid.length, cols = grid[0].length;
  const land = [];
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) if (grid[r][c] === 1) land.push(r * cols + c);
  const islandsWithout = removed => {
    const parent = new Map();
    const find = x => { while (parent.get(x) !== x) x = parent.get(x); return x; };
    for (const cell of land) if (!removed.has(cell)) parent.set(cell, cell);
    for (const cell of parent.keys()) {
      const r = Math.floor(cell / cols), c = cell % cols;
      if (c + 1 < cols && parent.has(cell + 1)) parent.set(find(cell), find(cell + 1));
      if (r + 1 < rows && parent.has(cell + cols)) parent.set(find(cell), find(cell + cols));
    }
    return new Set([...parent.keys()].map(find)).size;
  };
  const tryK = (k, start, removed) => {
    if (k === 0) return islandsWithout(removed) !== 1;
    for (let i = start; i < land.length; i++) {
      removed.add(land[i]);
      const ok = tryK(k - 1, i + 1, removed);
      removed.delete(land[i]);
      if (ok) return true;
    }
    return false;
  };
  for (let k = 0; ; k++) if (tryK(k, 0, new Set())) return k;
}

