function generate(rand, size) {
  const rows = size === 'large' ? 20 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 4);
  const cols = size === 'large' ? 20 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 4);
  const grid = Array.from({ length: rows }, () => new Array(cols).fill(0));
  const mode = rand();
  if (mode < 0.3) {
    // Scattered land: often several islands or none.
    const density = rand();
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) grid[r][c] = rand() < density ? 1 : 0;
  } else if (mode < 0.85) {
    // Grow one island cell by cell from a random start.
    const target = 1 + Math.floor(rand() * rows * cols * (size === 'large' ? 0.6 : 1));
    const frontier = [[Math.floor(rand() * rows), Math.floor(rand() * cols)]];
    let placed = 0;
    while (placed < target && frontier.length > 0) {
      const pick = Math.floor(rand() * frontier.length);
      const [r, c] = frontier[pick];
      frontier[pick] = frontier[frontier.length - 1];
      frontier.pop();
      if (grid[r][c] === 1) continue;
      grid[r][c] = 1;
      placed++;
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] === 0) frontier.push([nr, nc]);
      }
    }
  } else {
    // A solid rectangle of land, possibly with one hole punched in it.
    const top = Math.floor(rand() * rows), left = Math.floor(rand() * cols);
    const bottom = top + Math.floor(rand() * (rows - top)), right = left + Math.floor(rand() * (cols - left));
    for (let r = top; r <= bottom; r++) for (let c = left; c <= right; c++) grid[r][c] = 1;
    if (rand() < 0.5) grid[top + Math.floor(rand() * (bottom - top + 1))][left + Math.floor(rand() * (right - left + 1))] = 0;
  }
  return [grid];
}
